package ama.storage;
import java.util.*;import java.time.*;import java.math.*;import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;
class Task11Fix02RowPreimageTest {
 @Test void allJdbcTypesAreStableWithoutJacksonTemporalModules()throws Exception{var row=new LinkedHashMap<String,Object>();row.put("datetime",LocalDateTime.parse("2026-10-25T09:24:39.153640"));row.put("timestamp",java.sql.Timestamp.valueOf("2026-10-25 09:24:39.153640"));row.put("date",java.sql.Date.valueOf("2026-10-25"));row.put("time",java.sql.Time.valueOf("09:24:39"));row.put("localDate",LocalDate.of(2026,10,25));row.put("localTime",LocalTime.parse("09:24:39.153640"));row.put("offset",OffsetDateTime.parse("2026-10-25T09:24:39.153640+08:00"));row.put("instant",Instant.parse("2026-10-25T09:24:39.153640Z"));row.put("legacy",new java.util.Date(123456789));row.put("decimal",new BigDecimal("12345678901234567890.123400"));row.put("bigint",new BigInteger("123456789012345678901234567890"));row.put("bytes",new byte[]{0,-1,7});row.put("null",null);row.put("text","中文😀\u0000");row.put("int",12);row.put("long",12L);row.put("short",(short)12);row.put("byte",(byte)12);row.put("boolean",true);row.put("float",0.25f);row.put("double",0.25d);String hash=Task11Fix02RowPreimage.hash(List.of(row));assertEquals(64,hash.length());assertEquals(hash,Task11Fix02RowPreimage.hash(List.of(new TreeMap<>(row))));var copy=new LinkedHashMap<>(row);copy.put("bytes",new byte[]{0,-1,7});assertEquals(hash,Task11Fix02RowPreimage.hash(List.of(copy)));}
 @Test void typesScaleNullAndAnyTemporalPrecisionChangeRemainDistinct()throws Exception{assertNotEquals(hash(1),hash(1L));assertNotEquals(hash(1),hash(true));assertNotEquals(hash("1"),hash(1));assertNotEquals(hash(null),hash("NULL"));assertNotEquals(hash(new byte[]{1}),hash("AQ=="));assertNotEquals(hash(new BigDecimal("1.0")),hash(new BigDecimal("1.00")));assertNotEquals(hash(LocalDateTime.parse("2026-10-25T09:24:39.153640")),hash(LocalDateTime.parse("2026-10-25T09:24:39.153641")));assertNotEquals(hash(java.sql.Timestamp.valueOf("2026-10-25 09:24:39.153640")),hash(java.sql.Timestamp.valueOf("2026-10-25 09:24:39.153641")));assertNotEquals(hash("中😀"),hash("中😃"));}
 @Test void columnsSortRowsPreserveOrderAndUnknownTypesFailClosed()throws Exception{var first=new LinkedHashMap<String,Object>();first.put("b",2);first.put("a",1);assertEquals(Task11Fix02RowPreimage.hash(List.of(first)),Task11Fix02RowPreimage.hash(List.of(Map.of("a",1,"b",2))));assertNotEquals(Task11Fix02RowPreimage.hash(List.of(Map.of("id",1),Map.of("id",2))),Task11Fix02RowPreimage.hash(List.of(Map.of("id",2),Map.of("id",1))));assertThrows(IllegalArgumentException.class,()->hash(new Object()));}
 String hash(Object value)throws Exception{var row=new HashMap<String,Object>();row.put("v",value);return Task11Fix02RowPreimage.hash(List.of(row));}
}
